import { ok, fail } from './result.js';
import { roundCents } from './money.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Validate that a date string is in YYYY-MM-DD format and represents a real date.
 * @param {string} dateString
 * @returns {boolean}
 */
function isValidDate(dateString) {
  const match = /^\d{4}-\d{2}-\d{2}$/.test(dateString);
  if (!match) return false;
  const date = new Date(dateString + 'T00:00:00Z');
  return !isNaN(date.getTime()) && date.toISOString().startsWith(dateString);
}

/**
 * Validate discount percent is a number between 0 and 100.
 * @param {unknown} value
 * @returns {boolean}
 */
function isValidDiscountPercent(value) {
  return typeof value === 'number' && value >= 0 && value <= 100;
}

/**
 * Calculate the total for a single invoice line (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount amount for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const discountPercent = line.discountPercent ?? 0;
  const discount = roundCents(lineTotal(line) * discountPercent / 100);
  return Math.max(0, discount);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const total = Math.max(0, subtotal - discount);
  return { subtotal, discount, total };
}

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: unknown }> }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  // Validate issue date format and validity
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Build enriched lines
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Get product from catalogue
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  const invoice = {
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  };

  return ok(invoice);
}

/**
 * Add or update a line on an invoice.
 * @param {{ status: string, lines: Array<{ sku: string, qty: number, name: string, unitPrice: number, vatRate: number }> }} invoice
 * @param {{ sku: string, qty: unknown }} params
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Get product from catalogue
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Create new invoice with updated lines
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex !== -1) {
    // Update existing line
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find line with SKU
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check that removing it won't leave the invoice with no lines
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new invoice without the line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Issue an invoice (assign a number and change status to 'issued').
 * @param {{ status: string, issueDate: string, lines: Array }} invoice
 * @param {string[]} existingNumbers - Invoice numbers already in use
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Generate next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  // Create new invoice with number and issued status
  const newInvoice = {
    ...invoice,
    number,
    status: 'issued',
  };

  return ok(newInvoice);
}

