test('removeLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'ICON-SET', qty: 2 },
      { sku: 'DES-HOUR', qty: 1 },
    ],
  });
  const invoice = r.value;
  const original = JSON.parse(JSON.stringify(invoice));
  removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(invoice, original);
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 2 }],
  });
  const invoice = r.value;
  const r2 = issueInvoice(invoice, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.status, 'issued');
  assert.equal(r2.value.number, 'INV-2025-0001');
});

test('issueInvoice uses nextInvoiceNumber correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-03-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const invoice = r.value;
  const r2 = issueInvoice(invoice, ['INV-2025-0001', 'INV-2025-0002']);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2025-0003');
});

test('issueInvoice handles different years', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const invoice = r.value;
  const r2 = issueInvoice(invoice, ['INV-2025-0999']);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0001');
});

test('issueInvoice rejects non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'issued',
    number: 'INV-2025-0001',
    lines: [{ sku: 'ICON-SET', qty: 1, name: 'Icon set (24 icons)', unitPrice: 980, vatRate: 21 }],
  };
  const r = issueInvoice(invoice, []);
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice preserves other invoice data', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 2 }],
  });
  const invoice = r.value;
  const r2 = issueInvoice(invoice, []);
  assert.equal(r2.value.customerId, 'C-001');
  assert.equal(r2.value.issueDate, '2025-01-15');
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].qty, 2);
});

test('issueInvoice does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 2 }],
  });
